    {
      "id": "H1a",
      "title": "Precedence collapse",
      "arrivesWith": "the harvest task, not this tag"
    },
    {
      "id": "H1b",
      "title": "Audit fidelity, denied recorded as allowed",
      "arrivesWith": "the harvest task, not this tag"
    }
